/**
 * Maps an original image path to its downscaled thumbnail copy.
 *
 * Thumbnails live under `public/images/thumbs/**` and are generated by
 * `scripts/make-thumbs.mjs`. Used for small grid slots so they don't download
 * full-resolution originals. Full-bleed/hero images keep the original path.
 */
export function thumb(src: string): string {
  if (!src.startsWith("/images/") || src.startsWith("/images/thumbs/")) return src;
  return src.replace(/^\/images\//, "/images/thumbs/");
}
